      "takeaway": {
        "en": "Eliminate incorrect options immediately by inspecting unit digits: if a number ends in 2, 3, 7, or 8, it can never be a perfect square.",
        "mal": "ഒറ്റയുടെ സ്ഥാനത്തെ അക്കം നോക്കി ഉത്തരം കണ്ടെത്താം: 2, 3, 7, 8 എന്നിവയിൽ അവസാനിക്കുന്ന സംഖ്യകൾ ഒരിക്കലും പൂർണ്ണ വർഗ്ഗമാകില്ല."
      }
